import { test, expect } from '@playwright/test';

test.describe('File Download Functionality', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/files');
  });

  test('should successfully download a previously uploaded file', async ({ page }) => {
    // Intercept the download request
    await page.route('**/api/files/download/*', (route) => {
      route.continue();
    });

    // Upload a file first
    const fileInput = page.getByLabel('Upload file');
    await fileInput.setInputFiles('playwright/fixtures/sample.pdf');
    const uploadButton = page.getByRole('button', { name: 'Upload' });
    await uploadButton.click();

    // Wait for upload confirmation
    const successMessage = page.getByText('File uploaded successfully');
    await expect(successMessage).toBeVisible();

    // Verify file appears in list
    const fileItem = page.getByText('sample.pdf');
    await expect(fileItem).toBeVisible();

    // Click download button
    const downloadButton = page.getByRole('button', { name: 'Download' });
    await downloadButton.click();

    // Verify download prompt appears
    const downloadPrompt = page.getByText('Download sample.pdf');
    await expect(downloadPrompt).toBeVisible();

    // Verify download link is active
    const downloadLink = page.getByRole('link', { name: 'Download sample.pdf' });
    await expect(downloadLink).toBeEnabled();
  });

  test('should handle download failure when file is not found', async ({ page }) => {
    // Intercept the download request and simulate 404 error
    await page.route('**/api/files/download/*', (route) => {
      route.abort('failed');
    });

    // Navigate to file list
    await page.goto('/files');

    // Verify file list is visible
    const fileList = page.getByRole('region', { name: 'File List' });
    await expect(fileList).toBeVisible();

    // Attempt to download a non-existent file
    const downloadButton = page.getByRole('button', { name: 'Download' });
    await downloadButton.click();

    // Verify error message is displayed
    const errorMessage = page.getByText('File not found');
    await expect(errorMessage).toBeVisible();

    // Verify download prompt does not appear
    const downloadPrompt = page.getByText('Download');
    await expect(downloadPrompt).not.toBeVisible();

    // Verify download button is disabled after error
    await expect(downloadButton).toBeDisabled();
  });
});
